{
  "name": "数据采集流水线阶段",
  "name_en": "Acquisition Pipeline Stage",
  "manufacturer": "",
  "description": "用于实验数据采集系统中的单个处理阶段的软件组件，负责在采集流水线中组织进程、队列和消息传递，并可配置具体处理类。它常用于高通量实验或探测器数据流的在线处理、分发、预处理以及按批次标识保存数据。",
  "description_en": "A software component representing a single stage in an experimental data acquisition pipeline. It manages processes, queues, and message passing, and can be configured with a specific processing class. It is used for online handling, routing, preprocessing, and train-ID-based saving of streaming experimental or detector data.",
  "tag_hints": [
    "data acquisition pipeline",
    "stream processing",
    "multiprocessing",
    "inter-process queues",
    "message passing",
    "online data processing",
    "ZeroMQ"
  ],
  "actions": [
    {
      "action_name": "auto-stage",
      "description": "获取/设置流水线中的阶段位置。",
      "description_en": "Get/set the stage position in the pipeline."
    },
    {
      "action_name": "auto-numProcess",
      "description": "获取/设置构建时要启动的进程数量。",
      "description_en": "Get/set the number of processes to spawn when built."
    },
    {
      "action_name": "auto-configureStage",
      "description": "配置该采集阶段所使用的处理类及其参数。",
      "description_en": "Configure the processing class and its parameters for this acquisition stage."
    },
    {
      "action_name": "auto-setArgs",
      "description": "设置该阶段的初始化参数。",
      "description_en": "Set the initialization arguments for this stage."
    },
    {
      "action_name": "auto-processes",
      "description": "获取该阶段当前管理的进程对象。",
      "description_en": "Get the process objects currently managed by this stage."
    },
    {
      "action_name": "auto-build",
      "description": "构建该采集阶段并连接输入/输出队列。",
      "description_en": "Build the acquisition stage and connect its input/output queues."
    },
    {
      "action_name": "auto-outputQueue",
      "description": "获取该阶段的输出队列。",
      "description_en": "Get the output queue of this stage."
    },
    {
      "action_name": "auto-start",
      "description": "启动该采集阶段中的处理进程。",
      "description_en": "Start the processing workers in this acquisition stage."
    },
    {
      "action_name": "auto-stop",
      "description": "停止该采集阶段中的处理进程。",
      "description_en": "Stop the processing workers in this acquisition stage."
    },
    {
      "action_name": "auto-startTrainID",
      "description": "启动按 Train ID 直接保存数据的工作流程。",
      "description_en": "Start the workflow that saves data directly using Train ID."
    },
    {
      "action_name": "auto-stopTrainID",
      "description": "停止按 Train ID 保存数据的工作流程。",
      "description_en": "Stop the workflow that saves data using Train ID."
    }
  ]
}

